"""Build meta.json. Every `quote` is checked to be a verbatim substring (whitespace-normalised) of
anc/arxiv-2506.20661v1.txt (text of the arXiv v1 HTML; math kept as LaTeX alt-text), of the ancillary
.docx texts, or of the AWG command PDF text.  Run after verify.py:  python -I build_meta.py
"""
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import awg_parse as A  # noqa: E402


def norm(s):
    return ' '.join(s.replace('\xa0', ' ').split())


SRC = {
    'paper': norm(open(os.path.join(HERE, 'anc', 'arxiv-2506.20661v1.txt'), encoding='utf-8').read()),
    'Error_model.docx': norm(open(os.path.join(HERE, 'anc', 'Error_model.docx.txt'), encoding='utf-8').read()),
    'SIGuide.docx': norm(open(os.path.join(HERE, 'anc', 'SIGuide.docx.txt'), encoding='utf-8').read()),
    'Movie_captions.docx': norm(open(os.path.join(HERE, 'anc', 'Movie_captions.docx.txt'), encoding='utf-8').read()),
}
secs = A.read_sections(os.path.join(HERE, 'anc', 'RawExperimentalCommands_SurfaceCodeQEC.pdf'))
SRC['RawExperimentalCommands_SurfaceCodeQEC.pdf'] = norm(' '.join(v['preamble_prose'] + ' ' + ' '.join(v['commands']) for v in secs.values()))

BAD = []


def Q(quote, section, source='paper'):
    if norm(quote) not in SRC[source]:
        BAD.append((source, quote))
    return {'quote': quote, 'section': section, 'source': source}


def T(name, value, unit, quote, section, source='paper', **kw):
    d = {'name': name, 'value': value, 'unit': unit}
    d.update(Q(quote, section, source))
    d.update(kw)
    return d


